function LessonOverview({lesson,design,blocks,checked=[],toggleCheck,setTab,openLesson}){const allParas=blocks.filter(b=>b.type==='paragraph'&&b.paragraph?.text&&b.paragraph.text.trim());const steps=allParas.filter(b=>/^\d+\./.test(b.paragraph.text));const shown=steps.slice(0,10);const doneN=shown.filter((_,i)=>checked.includes(i)).length;const idxPasso=allParas.findIndex(b=>/^\d+\./.test(b.paragraph.text));const naoPasso=b=>!/^\d+\./.test(b.paragraph.text)&&!b.paragraph.headingLevel;const prosa=(idxPasso<0?allParas:allParas.slice(0,idxPasso)).filter(naoPasso);const notas=idxPasso<0?[]:allParas.slice(idxPasso).filter(naoPasso);const nTab=blocks.filter(b=>b.type==='table').length;const kids=lesson.number?lessons.filter(l=>l.number&&l.number!==lesson.number&&l.number.startsWith(lesson.number+'.')&&l.number.slice(lesson.number.length+1).replace(/\.$/,'').split('.').length===1):[];const parent=lesson.number&&lesson.number.includes('.')?lesson.number.slice(0,lesson.number.lastIndexOf('.')):'';const irmaos=parent?lessons.filter(l=>l.id!==lesson.id&&l.number&&l.number.startsWith(parent+'.')&&l.number.slice(parent.length+1).replace(/\.$/,'').split('.').length===1):[];const vazia=allParas.length===0&&nTab===0;return <article className="lesson-article"><h2>{lesson.number?lesson.number+' · ':''}{lesson.title}</h2><p className="lead">{vazia?'Esta seção organiza o percurso; use os tópicos relacionados para demonstrar o objetivo.':(kids.length?'Esta seção reúne os tópicos abaixo. Estude cada um e volte ao desafio de transferência.':design.objective)}</p><blockquote className="learning-source-basis"><small>EVIDÊNCIA-BASE DA SEÇÃO</small><p>{design.sourceBasis}</p><button type="button" onClick={()=>setTab&&setTab('fonte')}>Conferir na fonte <ArrowRight/></button></blockquote>{kids.length>0&&<nav className="lesson-children"><strong><Layers3 size={15}/> Tópicos desta seção</strong>{kids.map(c=><button key={c.id} onClick={()=>openLesson&&openLesson(c.id)}><span>{c.number}</span><em>{c.title}</em><ChevronRight size={15}/></button>)}</nav>}{nTab>0&&prosa.every(b=>/^(Quadro|Tabela|Figura)s*d/.test(b.paragraph.text))&&<div className="kp-quadro"><p className="kp-quadro-nota"><Table2 size={15}/> O conteúdo desta seção é um quadro do POP. Ele está abaixo, e também na aba Quadros e figuras.</p>{blocks.filter(b=>b.type==='table').map(b=>{const t=tableMap.get(b.tableId);return t?<TableRenderer key={b.id} table={t}/>:null})}</div>}{prosa.length>0&&<div className="lesson-keypoints">{prosa.slice(0,3).map(b=><p key={b.id}>{b.paragraph.text}</p>)}{prosa.length>3&&<button className="kp-mais" onClick={()=>setTab&&setTab('fonte')}><FileText size={15}/> Conferir todos os {prosa.length} parágrafos na fonte da seção</button>}</div>}{steps.length>=3?<div className="lesson-checklist"><div className="lc-head"><strong><ClipboardCheck size={16}/> Checklist da aula</strong><span>{doneN}/{shown.length} verificados</span><i><em style={{width:`${shown.length?doneN/shown.length*100:0}%`}}/></i></div>{shown.map((b,i)=>{const on=checked.includes(i);return <button type="button" key={b.id} className={on?'lc-item done':'lc-item'} aria-pressed={on} onClick={()=>toggleCheck&&toggleCheck(i)}>{on?<CheckCircle2/>:<Circle/>}<span>{b.paragraph.text.replace(/^\d+\.\s*/,'')}</span></button>})}{doneN===shown.length&&<div className="lc-complete"><Check/> Checklist percorrido. Agora confronte os itens com a evidência do caso; marcar não prova suficiência.</div>}</div>:null}{notas.length>0&&<div className="lesson-keypoints kp-notas"><strong className="kp-notas-tit"><Info size={15}/> Observações do procedimento</strong>{notas.slice(0,3).map(b=><p key={b.id}>{b.paragraph.text}</p>)}</div>}{vazia&&irmaos.length>0&&<nav className="lesson-children lc-related"><strong><GitBranch size={15}/> Tópicos relacionados nesta parte</strong>{irmaos.slice(0,12).map(c=><button key={c.id} onClick={()=>openLesson&&openLesson(c.id)}><span>{c.number}</span><em>{c.title}</em><ChevronRight size={15}/></button>)}</nav>}{!vazia&&<><div className="analysis-alert"><AlertTriangle/><div><strong>Limite de aplicação</strong><p>Este conteúdo ensina a aplicar o POP. Antes de decidir em processo real, confirme norma vigente, regra de transição, competência e orientação institucional aplicável.</p></div></div><div className="example-compare"><div className="bad"><X/><div><strong>Atalho arriscado</strong><p>Assumir a conclusão e procurar documentos apenas para confirmá-la.</p></div></div><div className="good"><Check/><div><strong>Análise rastreável</strong><p>Confrontar evidências, registrar limitações e deixar a conclusão resultar do percurso.</p></div></div></div></>}{(prosa.length>0||steps.length>0||nTab>0)&&<button className="source-jump" onClick={()=>setTab&&setTab('fonte')}><BookMarked/> Conferir o trecho na fonte da seção</button>}</article>}
function SourceContent({blocks}){if(!blocks.length)return <Empty text="Esta seção funciona como título de organização. O conteúdo substantivo está nos subtópicos vinculados; a ausência de texto aqui não deve ser interpretada como cobertura integral."/>;return <article className="source-content"><div className="source-notice"><ShieldCheck/><p><strong>Trechos vinculados ao documento-fonte.</strong> Esta aba reproduz os blocos associados à seção e suas tabelas. Sumário e elementos de navegação podem estar fora desta visualização; confira o arquivo original antes de usar o conteúdo em decisão real.</p></div>{blocks.map(b=><BlockRenderer block={b} key={b.id}/>)}</article>}
function BlockRenderer({block}){if(block.type==='table'){const table=tableMap.get(block.tableId);return table?<TableRenderer table={table}/>:null}const p=block.paragraph;if(!p?.text)return null;const figure=figureByBlock.get(block.id);let text=p.text;let cls=p.semanticType==='list-item'||p.list?'source-list':'';return <React.Fragment>{p.headingLevel?<h3>{text}</h3>:<p className={cls}>{text}</p>}{figure&&<figure className="source-figure"><img src={figure.publicPath} alt={figure.altText||figure.title}/><figcaption>{figure.caption}</figcaption></figure>}</React.Fragment>}
